        :root{--navy:#071a35;--ink:#10213b;--muted:#64748b;--line:#e4ebf4;--teal:#16818a}*{box-sizing:border-box}body{margin:0;background:#f3f7fb;color:var(--ink);font:15px/1.65 "Segoe UI",Arial,sans-serif}.shell{width:min(1180px,calc(100% - 32px));margin:auto;padding:24px 0 48px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.brand{display:flex;align-items:center;gap:11px;font-weight:800;color:var(--navy)}.brand img{width:38px;height:38px;object-fit:contain}.top a{display:inline-flex;align-items:center;gap:8px;text-decoration:none;font-weight:700;color:#285071;background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 14px}.hero{padding:34px;border-radius:22px;color:#fff;background:linear-gradient(120deg,#10283d,#145d69 62%,#1c8d83);box-shadow:0 16px 34px #10283d20}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:11px;font-weight:800;opacity:.75}.hero h1{font-size:clamp(28px,4vw,42px);line-height:1.2;margin:8px 0}.hero p{max-width:760px;margin:0;opacity:.86}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.chip{padding:5px 10px;border-radius:99px;background:#ffffff1c;font-size:12px;font-weight:700}.layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:18px;margin-top:18px}.nav,.card{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 8px 22px #13233b0b}.nav{padding:16px;height:max-content;position:sticky;top:16px}.nav strong{display:block;padding:5px 9px 9px;color:#77859a;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.nav a{display:block;padding:8px 10px;border-radius:9px;color:#45556c;text-decoration:none;font-size:13px}.nav a:hover{background:#eaf4f4;color:#135d66}.content{min-width:0}.card{padding:22px;margin-bottom:15px;scroll-margin-top:15px}.card h2{font-size:21px;margin:3px 0 9px}.card h3{font-size:16px;margin:14px 0 6px}.kicker{color:#708097;font-size:11px;text-transform:uppercase;letter-spacing:.09em;font-weight:800}.muted{color:var(--muted)}.callout{border-left:4px solid #d59b23;background:#fff9e8;padding:12px 15px;border-radius:0 10px 10px 0;margin-top:13px}.callout.info{border-color:#21868c;background:#effafa}.steps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.step{border:1px solid var(--line);border-radius:12px;padding:14px;display:flex;gap:12px}.num{flex:0 0 29px;height:29px;border-radius:9px;display:grid;place-items:center;background:#e9f3f4;color:#176b78;font-weight:800}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:9px 10px;border:1px solid var(--line);vertical-align:top}th{background:#f5f8fb;white-space:nowrap}code{font-family:Consolas,monospace;color:#145b72;overflow-wrap:anywhere}.code{background:#101c2d;color:#d8e5f7;border-radius:12px;padding:15px;overflow:auto;font:12px/1.65 Consolas,monospace;white-space:pre}.code code{color:inherit}.footer{color:#718096;text-align:center;font-size:12px;padding-top:10px}@media(max-width:760px){.shell{width:min(100% - 22px,1180px);padding-top:12px}.hero{padding:23px}.layout{grid-template-columns:1fr}.nav{position:static;display:flex;overflow:auto;white-space:nowrap;gap:3px}.nav strong{display:none}.nav a{display:inline-block}.steps{grid-template-columns:1fr}.card{padding:17px}.top a span{display:none}}
